typedef long long ll;

typedef struct {
    int x, y, z;
    ll vol;
} Doll;

static int cmp_doll(const void *a, const void *b) {
    const Doll *A = (const Doll *)a;
    const Doll *B = (const Doll *)b;
    if (A->x != B->x) return (A->x < B->x) ? -1 : 1;
    if (A->y != B->y) return (A->y < B->y) ? -1 : 1;
    if (A->z != B->z) return (A->z < B->z) ? -1 : 1;
    return 0;
}

/* Hopcroft-Karp for bipartite matching */
static int *adjHead, *adjTo, *adjNext, edgeCnt;
static int *distHK, *matchL, *matchR;
static int nLeft, nRight;

static void addEdge(int u, int v) {
    adjTo[edgeCnt] = v;
    adjNext[edgeCnt] = adjHead[u];
    adjHead[u] = edgeCnt++;
}

static int bfs(void) {
    int *q = (int *)malloc((nLeft + 5) * sizeof(int));
    int qh = 0, qt = 0;
    int found = 0;

    for (int i = 1; i <= nLeft; i++) {
        if (matchL[i] == 0) {
            distHK[i] = 0;
            q[qt++] = i;
        } else {
            distHK[i] = -1;
        }
    }

    while (qh < qt) {
        int u = q[qh++];
        for (int e = adjHead[u]; e != -1; e = adjNext[e]) {
            int v = adjTo[e];
            int mu = matchR[v];
            if (mu == 0) {
                found = 1;
            } else if (distHK[mu] == -1) {
                distHK[mu] = distHK[u] + 1;
                q[qt++] = mu;
            }
        }
    }

    free(q);
    return found;
}

static int dfs(int u) {
    for (int e = adjHead[u]; e != -1; e = adjNext[e]) {
        int v = adjTo[e];
        int mu = matchR[v];
        if (mu == 0 || (distHK[mu] == distHK[u] + 1 && dfs(mu))) {
            matchL[u] = v;
            matchR[v] = u;
            return 1;
        }
    }
    distHK[u] = -1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Doll *a = (Doll *)malloc(N * sizeof(Doll));
    ll totalVolume = 0;

    for (int i = 0; i < N; i++) {
        int d[3];
        scanf("%d %d %d", &d[0], &d[1], &d[2]);

        /* Rotate freely: sort dimensions so comparison is consistent */
        for (int p = 0; p < 3; p++) {
            for (int q = p + 1; q < 3; q++) {
                if (d[p] > d[q]) {
                    int t = d[p];
                    d[p] = d[q];
                    d[q] = t;
                }
            }
        }

        a[i].x = d[0];
        a[i].y = d[1];
        a[i].z = d[2];
        a[i].vol = 1LL * d[0] * d[1] * d[2];
        totalVolume += a[i].vol;
    }

    qsort(a, N, sizeof(Doll), cmp_doll);

    /*
      Build bipartite graph:
      left i -> right j if doll i can be put inside doll j.
      Each doll can contain at most one doll and can be inside at most one doll.
      Maximum matching gives maximum number of hidden dolls.
      To minimize visible volume, maximize sum of volumes of hidden dolls.
      Since an edge always goes from strictly smaller to strictly larger, the graph is acyclic.
      We use maximum-cardinality matching; among all hidden dolls, every matched left doll is hidden.
      The visible volume becomes total - sum(hidden volumes).

      However, cardinality alone is not enough if volumes differ.
      But because each hidden doll contributes exactly its own volume and each doll can be hidden at most once,
      we need a maximum-weight matching on this DAG-like comparability graph.
      We can transform it to min-cost max-flow, but simpler:
      weight depends only on chosen left vertices. So we solve min-cost max-flow.
    */

    /* Build min-cost max-flow graph */
    int S = 0;
    int Lbase = 1;
    int Rbase = Lbase + N;
    int T = Rbase + N;
    int V = T + 1;

    int maxEdges = 2 * (N + N + (N * (N - 1) / 2)) + 10;
    int *head = (int *)malloc(V * sizeof(int));
    int *to = (int *)malloc(maxEdges * sizeof(int));
    int *next = (int *)malloc(maxEdges * sizeof(int));
    int *cap = (int *)malloc(maxEdges * sizeof(int));
    ll *cost = (ll *)malloc(maxEdges * sizeof(ll));
    int ec = 0;

    for (int i = 0; i < V; i++) head[i] = -1;

    #define ADD_EDGE(u,v,c,w) do { \
        to[ec] = (v); cap[ec] = (c); cost[ec] = (w); next[ec] = head[(u)]; head[(u)] = ec++; \
        to[ec] = (u); cap[ec] = 0; cost[ec] = -(w); next[ec] = head[(v)]; head[(v)] = ec++; \
    } while (0)

    for (int i = 0; i < N; i++) {
        ADD_EDGE(S, Lbase + i, 1, -a[i].vol);   /* choose hiding doll i gains volume a[i] */
        ADD_EDGE(Lbase + i, T, 1, 0);           /* or leave it visible */
    }
    for (int j = 0; j < N; j++) {
        ADD_EDGE(Rbase + j, T, 1, 0);
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (a[i].x < a[j].x && a[i].y < a[j].y && a[i].z < a[j].z) {
                ADD_EDGE(Lbase + i, Rbase + j, 1, 0);
            }
        }
    }

    /* Min-cost max-flow sending up to N units from S to T */
    ll minCost = 0;
    int flow = 0;

    ll *dist = (ll *)malloc(V * sizeof(ll));
    int *inq = (int *)malloc(V * sizeof(int));
    int *pv = (int *)malloc(V * sizeof(int));
    int *pe = (int *)malloc(V * sizeof(int));
    int *q = (int *)malloc((V * 4 + 10) * sizeof(int));

    while (1) {
        const ll INF = (1LL << 60);
        for (int i = 0; i < V; i++) {
            dist[i] = INF;
            inq[i] = 0;
            pv[i] = -1;
            pe[i] = -1;
        }

        int qh = 0, qt = 0;
        dist[S] = 0;
        q[qt++] = S;
        inq[S] = 1;

        while (qh != qt) {
            int u = q[qh++];
            if (qh == V * 4 + 10) qh = 0;
            inq[u] = 0;

            for (int e = head[u]; e != -1; e = next[e]) {
                if (cap[e] <= 0) continue;
                int v = to[e];
                if (dist[v] > dist[u] + cost[e]) {
                    dist[v] = dist[u] + cost[e];
                    pv[v] = u;
                    pe[v] = e;
                    if (!inq[v]) {
                        q[qt++] = v;
                        if (qt == V * 4 + 10) qt = 0;
                        inq[v] = 1;
                    }
                }
            }
        }

        if (dist[T] >= 0 || dist[T] == (1LL << 60)) break;

        int addf = 1;
        for (int v = T; v != S; v = pv[v]) {
            if (pv[v] == -1) { addf = 0; break; }
            if (cap[pe[v]] < addf) addf = cap[pe[v]];
        }
        if (!addf) break;

        for (int v = T; v != S; v = pv[v]) {
            cap[pe[v]] -= addf;
            cap[pe[v] ^ 1] += addf;
        }
        flow += addf;
        minCost += dist[T] * addf;
    }

    ll hiddenVolume = -minCost;
    ll answer = totalVolume - hiddenVolume;
    printf("%lld\n", answer);

    free(a);
    free(head);
    free(to);
    free(next);
    free(cap);
    free(cost);
    free(dist);
    free(inq);
    free(pv);
    free(pe);
    free(q);

    return 0;
}

