import java.io.*;
import java.util.*;

/*
We need minimize total visible volume after nesting.
Each doll can contain at most one other doll, and each doll can be inside at most one other.
A nesting i -> j is possible if all three dimensions of i are strictly smaller than j after reordering dimensions per doll.
Visible volume = sum(volumes of dolls not inside another doll).
If doll A contains B, visible volume decreases by volume(B), regardless of A.

Thus minimizing visible volume = maximizing total volume of dolls that are placed inside some other doll.
This is a maximum weight matching in a DAG/poset where edge i->j if i fits in j, with weight volume(i) for matching i as inner.
Because each node has out-capacity 1 (as inner once) and in-capacity 1 (as outer once), it's a bipartite matching:
left copy = possible inner dolls, right copy = possible outer dolls, edge L_i -> R_j if i fits in j.
Weight depends only on left node matched: volume(i).

Need max-weight bipartite matching in graph up to unknown N. We can solve via min-cost max-flow:
source -> L_i cap1 cost -vol(i)
L_i -> R_j cap1 cost 0 if fits
R_j -> sink cap1 cost 0
Also allow not matching a left node by simply not sending flow through it. To maximize profit, repeatedly send negative-cost augmenting paths; equivalently run min-cost flow while shortest path cost < 0.

Complexities O(F * E log V), acceptable for moderate N. For dense graph N maybe up to a few hundred.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to, rev, cap;
        long cost;
        Edge(int to, int rev, int cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        void addEdge(int s, int t, int cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
        }

        long minCostForNegativePaths(int s, int t) {
            long totalCost = 0;
            long[] dist = new long[n];
            int[] pv = new int[n];
            int[] pe = new int[n];
            boolean[] inq = new boolean[n];

            final long INF = Long.MAX_VALUE / 4;

            while (true) {
                Arrays.fill(dist, INF);
                Arrays.fill(inq, false);
                dist[s] = 0;
                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(s);
                inq[s] = true;

                while (!q.isEmpty()) {
                    int v = q.poll();
                    inq[v] = false;
                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap > 0 && dist[v] + e.cost < dist[e.to]) {
                            dist[e.to] = dist[v] + e.cost;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            if (!inq[e.to]) {
                                inq[e.to] = true;
                                q.add(e.to);
                            }
                        }
                    }
                }

                if (dist[t] >= 0 || dist[t] == INF) break;

                int add = Integer.MAX_VALUE;
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    add = Math.min(add, e.cap);
                }

                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    e.cap -= add;
                    g[v].get(e.rev).cap += add;
                }

                totalCost += dist[t] * add;
            }

            return totalCost;
        }
    }

    static boolean fits(long[] a, long[] b) {
        return a[0] < b[0] && a[1] < b[1] && a[2] < b[2];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[][] d = new long[N][3];
        long[] vol = new long[N];
        long total = 0;

        for (int i = 0; i < N; i++) {
            d[i][0] = fs.nextLong();
            d[i][1] = fs.nextLong();
            d[i][2] = fs.nextLong();
            Arrays.sort(d[i]);
            vol[i] = d[i][0] * d[i][1] * d[i][2];
            total += vol[i];
        }

        int S = 0;
        int L = 1;
        int R = L + N;
        int T = R + N;
        MinCostFlow mcf = new MinCostFlow(T + 1);

        for (int i = 0; i < N; i++) {
            mcf.addEdge(S, L + i, 1, -vol[i]);
            mcf.addEdge(R + i, T, 1, 0);
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i != j && fits(d[i], d[j])) {
                    mcf.addEdge(L + i, R + j, 1, 0);
                }
            }
        }

        long minCost = mcf.minCostForNegativePaths(S, T);
        long saved = -minCost;
        long answer = total - saved;

        System.out.println(answer);
    }
}

