struct Fenwick2D {
    int n;
    vector<vector<pair<int, long long>>> bit;
    Fenwick2D(int n) : n(n), bit(n + 1) {}

    void update(int x, int y, long long val) {
        for (int i = x; i <= n; i += i & -i) {
            for (auto &p : bit[i]) {
                if (p.first == y) {
                    p.second = max(p.second, val);
                    return;
                }
            }
            bit[i].push_back({y, val});
        }
    }

    long long query(int x, int y) {
        long long res = 0;
        for (int i = x; i > 0; i -= i & -i) {
            for (auto &p : bit[i]) {
                if (p.first <= y) {
                    res = max(res, p.second);
                }
            }
        }
        return res;
    }
};

