            if (dolls[i].a < dolls[j].a &&
                dolls[i].b < dolls[j].b &&
                dolls[i].c < dolls[j].c) {
                g[i].push_back(j);
            }
        }
    }

    // Maximum bipartite matching (Kuhn)
    vector<int> matchR(N, -1);

    function<bool(int, vector<int>&)> dfs = [&](int u, vector<int>& vis) -> bool {
        for (int v : g[u]) {
            if (vis[v]) continue;
            vis[v] = 1;
            if (matchR[v] == -1 || dfs(matchR[v], vis)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    };

    for (int i = 0; i < N; ++i) {
        vector<int> vis(N, 0);
        dfs(i, vis);
    }

    // A visible doll is one that does not get placed inside another doll.
    // In the matching, each matched left node is placed inside some right node.
    vector<int> usedAsInner(N, 0);
    for (int v = 0; v < N; ++v) {
        if (matchR[v] != -1) usedAsInner[matchR[v]] = 1;
    }

    int64 answer = 0;
    for (int i = 0; i < N; ++i) {
        if (!usedAsInner[i]) answer += dolls[i].vol;
    }

    cout << answer << '\n';
    return 0;
}

import sys
from collections import defaultdict

sys.setrecursionlimit(1000000)

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    dolls = []
    total_vol = 0
    for _ in range(n):
        dims = sorted([int(next(it)), int(next(it)), int(next(it))])
        x, y, z = dims
        vol = x * y * z
        total_vol += vol
        dolls.append((x, y, z, vol))

    # Build adjacency from inner to outer
    adj = [[] for _ in range(n)]
    for i in range(n):
        x1, y1, z1, _ = dolls[i]
        for j in range(n):
            if i == j:
                continue
            x2, y2, z2, _ = dolls[j]
            if x1 < x2 and y1 < y2 and z1 < z2:
                adj[i].append(j)

    # Maximum bipartite matching
    match_to = [-1] * n  # outer -> inner

    def dfs(u, visited):
        for v in adj[u]:
            if visited[v]:
                continue
            visited[v] = True
            if match_to[v] == -1 or dfs(match_to[v], visited):
                match_to[v] = u
                return True
        return False

    result = 0
    for i in range(n):
        visited = [False] * n
        if dfs(i, visited):
            result += 1

    # Hidden volume = sum of volumes of matched inner dolls
    hidden_vol = 0
    used_inner = [False] * n
    for outer, inner in enumerate(match_to):
        if inner != -1:
            if not used_inner[inner]:
                hidden_vol += dolls[inner][3]
                used_inner[inner] = True

    print(total_vol - hidden_vol)

